// The locale table: every configured locale's base href and route words, which the builders hand
// to package code as one Angular `define` (localeUrls reads it in _core/src/locale-urls.ts). It's
// computed in memory from angular.json and the catalogs generation validated; no generated file
// holds it, so generated bytes never depend on a catalog.
import { segmentId, type LocaleWords } from "../generation/localization.js";

/** The `define` identifier package code reads. */
export const localeTableKey = "loozoRouterLocales";

export interface LocaleTable {
  readonly locales: readonly {
    /** As configured in angular.json `i18n`: "de". */
    readonly code: string;
    /** That locale build's `<base href>`: "/de/". */
    readonly baseHref: string;
    /** Authored word → this locale's text, only where they differ, sorted by authored word. */
    readonly words: readonly (readonly [string, string])[];
  }[];
}

/** One locale as Angular's i18n options normalize it: an optional `baseHref` or a `subPath`. */
interface LocaleBase {
  readonly baseHref?: string;
  readonly subPath: string;
}

function record(value: unknown): Readonly<Record<string, unknown>> | undefined {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Readonly<Record<string, unknown>>;
  }

  return undefined;
}

function text(value: unknown): string | undefined {
  if (typeof value === "string") {
    return value;
  }

  return undefined;
}

// Angular's joinUrlParts (@angular/build 22.2 src/utils/url.js).
function joinUrlParts(...parts: string[]): string {
  const normalized: string[] = [];

  for (const part of parts) {
    if (part === "") {
      continue;
    }

    let trimmed = part;

    if (part.startsWith("/")) {
      trimmed = trimmed.slice(1);
    }

    if (part.endsWith("/")) {
      trimmed = trimmed.slice(0, -1);
    }

    if (trimmed !== "") {
      normalized.push(trimmed);
    }
  }

  const joined = normalized.join("/");

  if (normalized.length > 0 && /^https?:\/\//.test(normalized[0])) {
    return joined;
  }

  if (joined.startsWith("/")) {
    return joined;
  }

  return `/${joined}`;
}

/**
 * A locale build's base href as Angular 22.2's getLocaleBaseHref computes it
 * (src/builders/application/options.js), for output that isn't flat: the locale's `baseHref`, else
 * its `subPath` and a slash, joined under the build's `baseHref`. Undefined for an empty suffix,
 * where Angular keeps the build's own base.
 */
export function localeBaseHref(baseHref: string, locale: LocaleBase): string | undefined {
  const suffix = locale.baseHref ?? `${locale.subPath}/`;

  if (suffix === "") {
    return undefined;
  }

  let joined = joinUrlParts(baseHref, suffix);

  if (!joined.endsWith("/")) {
    joined = `${joined}/`;
  }

  // Angular's stripLeadingSlash, which leaves "/" alone.
  if (baseHref !== "" && !baseHref.startsWith("/") && joined.length > 1 && joined.startsWith("/")) {
    joined = joined.slice(1);
  }

  return joined;
}

/**
 * The configured locales in Angular's order (@angular/build 22.2 createI18nOptions): the source
 * locale (a code, `{ code, baseHref, subPath }`, or en-US when omitted) first, then `i18n.locales`
 * in order, each a translation file, a list, or `{ translation, baseHref, subPath }`. Angular
 * validates the configuration when it builds; a field of the wrong type reads as absent here.
 */
function configuredLocales(i18n: unknown): (LocaleBase & { readonly code: string })[] {
  const metadata = record(i18n) ?? {};
  const source = metadata.sourceLocale;
  let code = "en-US";
  let sourceBase: string | undefined;
  let sourcePath: string | undefined;

  if (typeof source === "string") {
    code = source;
  } else {
    const options = record(source);

    code = text(options?.code) ?? code;
    sourceBase = text(options?.baseHref);
    sourcePath = text(options?.subPath);
  }

  const locales: (LocaleBase & { readonly code: string })[] = [
    { code, baseHref: sourceBase, subPath: sourcePath ?? code },
  ];

  for (const [locale, value] of Object.entries(record(metadata.locales) ?? {})) {
    const options = record(value);
    let baseHref: string | undefined;
    let subPath: string | undefined;

    if (options && "translation" in options) {
      baseHref = text(options.baseHref);
      subPath = text(options.subPath);
    }

    locales.push({ code: locale, baseHref, subPath: subPath ?? locale });
  }

  return locales;
}

/**
 * The table for a build, or undefined when the build doesn't localize: `localize` is `true` or a
 * nonempty list. Every configured locale is listed, whatever `localize` selects, so separately
 * built locales agree. A locale whose base Angular leaves to the build (an empty suffix) gets the
 * build's `baseHref`, else "/".
 *
 * Served, the table exists only for a single-locale `localize` list, the one case Angular's dev
 * server localizes. Its output is flat, so the served locale's base is the build's `baseHref`,
 * else "/"; every other locale keeps its production base.
 *
 * @param words - Each non-source locale's text for every route word, from generation with
 * `translateSegments`; undefined lists no words.
 */
export function localeTable({
  i18n,
  baseHref,
  localize,
  served = false,
  words,
}: {
  i18n: unknown;
  baseHref: unknown;
  localize: unknown;
  served?: boolean;
  words: LocaleWords | undefined;
}): LocaleTable | undefined {
  let flat: string | undefined;

  if (served) {
    if (!Array.isArray(localize) || localize.length !== 1 || typeof localize[0] !== "string") {
      return undefined;
    }

    flat = localize[0];
  } else if (localize !== true && !(Array.isArray(localize) && localize.length > 0)) {
    return undefined;
  }

  const buildBase = text(baseHref) ?? "";
  let fallback = buildBase;

  if (fallback === "") {
    fallback = "/";
  }

  const locales: LocaleTable["locales"][number][] = [];

  for (const locale of configuredLocales(i18n)) {
    let base: string | undefined;

    if (locale.code !== flat) {
      base = localeBaseHref(buildBase, locale);
    }

    const pairs: [string, string][] = [];

    for (const [word, translation] of words?.get(locale.code) ?? []) {
      if (translation !== word) {
        pairs.push([word, translation]);
      }
    }

    pairs.sort(([a], [b]) => {
      if (a < b) {
        return -1;
      }

      if (a > b) {
        return 1;
      }

      return 0;
    });

    locales.push({ code: locale.code, baseHref: base ?? fallback, words: pairs });
  }

  return { locales };
}

/** One warning per locale whose base href is relative: localeUrls then gives relative URLs. */
export function localeTableWarnings(table: LocaleTable): string[] {
  const warnings: string[] = [];

  for (const { code, baseHref } of table.locales) {
    if (baseHref.startsWith("/") || /^https?:\/\//.test(baseHref)) {
      continue;
    }

    warnings.push(
      `Locale ${code}'s base href ${JSON.stringify(baseHref)} is relative: localeUrls gives relative URLs, which the browser resolves against the current page's base. Use a baseHref that starts with "/" or "http".`,
    );
  }

  return warnings;
}

/** Throws when an application's own `define` takes the table's key. */
export function checkDefine(define: unknown): void {
  const defined = record(define);

  if (defined && Object.hasOwn(defined, localeTableKey)) {
    throw new Error(
      `define.${localeTableKey} is reserved by @loozo/angular-router: remove it from the build options`,
    );
  }
}

/** `define` with the table added under its key; throws when the application already defines it. */
export function withLocaleTable(define: unknown, table: LocaleTable): Record<string, string> {
  checkDefine(define);

  const result: Record<string, string> = {};

  for (const [key, value] of Object.entries(record(define) ?? {})) {
    result[key] = value as string;
  }

  result[localeTableKey] = JSON.stringify(table);

  return result;
}

/**
 * The serve warning for a table that differs from the one the dev server started with, naming up
 * to three of the words that differ.
 */
export function changedTableWarning(started: LocaleTable, current: LocaleTable): string {
  const changes: string[] = [];

  for (const locale of current.locales) {
    const before = new Map(started.locales.find(({ code }) => code === locale.code)?.words ?? []);
    const after = new Map(locale.words);

    for (const word of [...new Set([...before.keys(), ...after.keys()])].sort()) {
      if (before.get(word) !== after.get(word)) {
        changes.push(`${segmentId(word)} in ${locale.code}`);
      }
    }
  }

  let named = changes.slice(0, 3).join(", ");

  if (changes.length > 3) {
    named = `${named} and ${changes.length - 3} more`;
  }

  return `Locale words changed (${named}). Links from localeUrls keep the words ng serve started with until you restart it.`;
}
